    @EventHandler( payloadType=UpdateMerchantEvent.class )
    public void handle( UpdateMerchantEvent event) {
    	LOGGER.info("handling UpdateMerchantEvent - " + event );
    	
	    Merchant entity = new Merchant();
            entity.setMerchantId( event.getMerchantId() );
            entity.setName( event.getName() );
            entity.setLegalName( event.getLegalName() );
            entity.setWebsite( event.getWebsite() );
            entity.setDefaultCurrency( event.getDefaultCurrency() );
            entity.setDefaultLocale( event.getDefaultLocale() );
            entity.setSupportEmail( event.getSupportEmail() );
            entity.setChannels( event.getChannels() );
            entity.setBrands( event.getBrands() );
            entity.setFulfillmentCenters( event.getFulfillmentCenters() );
            entity.setTaxRules( event.getTaxRules() );
            entity.setPaymentProviders( event.getPaymentProviders() );
            entity.setSellers( event.getSellers() );
            entity.setPromotions( event.getPromotions() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindMerchant( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllMerchant( entity );        
    }
    
